sys_script_fix.script:
var eventId = 'EVT0001016'; // Replace with your Event sys_id

var budgetGR = new GlideRecord('x_1790229_event_ma_budget'); // Replace with your actual Budget table name
budgetGR.addQuery('u_event_id.number', eventId); // Assuming 'u_event' is the reference to the Event table
budgetGR.query();

while (budgetGR.next()) {
    gs.info('Budget id: ' + budgetGR.getDisplayValue('number'));     // Adjust field name
    gs.info('Allocated Amount: ' + budgetGR.getValue('u_total_budget'));  // e.g., in currency
    gs.info('Amount Spent: ' + budgetGR.getValue('u_amount_spent'));
    gs.info('Remaining Amount: ' + budgetGR.getValue('u_amount_remaining'));
    gs.info('Status: ' + budgetGR.getDisplayValue('u_status'));
    gs.info('-----');
}
